import { InvitesTab } from "@/components/management/invite-tab";
import { StaffDetailTabs } from "./staff-detail-tabs";
import { Staff } from "../page";

export function StaffDetailContent({
  activeId,
  active,
  setStaff,
  staff,
  setActiveId,
}: {
  activeId: string;
  active: Staff | undefined;
  setStaff: React.Dispatch<React.SetStateAction<Staff[]>>;
  staff: Staff[];
  setActiveId: React.Dispatch<React.SetStateAction<string>>;
}) {
  if (activeId === "invites") {
    return <InvitesTab />;
  }

  if (active) {
    return (
      <StaffDetailTabs
        active={active}
        staff={staff}
        setStaff={setStaff}
        activeId={activeId}
        setActiveId={setActiveId}
      />
    );
  }

  return (
    <p className="text-sm text-muted-foreground">
      Choose a staff member to edit details.
    </p>
  );
}
